$nombre=$_SESSION['nombre'] ?? 'Administrador'; $rol=$_SESSION['rol']; $mensaje=''; $error=false;
function e($v){ return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function postInt($k){ return filter_input(INPUT_POST,$k,FILTER_VALIDATE_INT) ?: 0; }
function auditUser(PDO $pdo){ $s=$pdo->prepare('SET @usuario_app = ?'); $s->execute([$_SESSION['usuario']]); }
function friendly(PDOException $e){ $m=$e->getMessage(); if(stripos($m,'Duplicate')!==false) return 'Ya existe un registro con alguno de los datos únicos proporcionados.'; if(stripos($m,'materias requisito')!==false) return 'El alumno no cumple con los prerrequisitos necesarios para esta materia.'; return 'No fue posible completar la operación. Verifica los datos y sus relaciones.'; }
try{if($_SERVER['REQUEST_METHOD']==='POST'){ $a=$_POST['accion']??''; if($a==='grupo'){ $n=trim($_POST['nombre']??'');$per=postInt('periodo');$c=(int)$_POST['cupo'];if(!$n||!$per||$c<1)throw new Exception('Datos de grupo inválidos.');$s=$pdo->prepare('INSERT INTO grupos(nombre,id_periodo,cupo_maximo,estado) VALUES(?,?,?,1)');$s->execute([$n,$per,$c]);$mensaje='Grupo creado.';} if($a==='asignar'){ $s=$pdo->prepare('INSERT INTO materia_profesor(profesor,materia,grupo) VALUES(?,?,?)');$s->execute([postInt('profesor'),postInt('materia'),postInt('grupo')]);$mensaje='Profesor asignado.';} if($a==='inscribir'){ $al=postInt('alumno');$as=postInt('asignacion');$g=$pdo->prepare('SELECT grupo FROM materia_profesor WHERE id=?');$g->execute([$as]);$gid=(int)$g->fetchColumn();$c=$pdo->prepare("SELECT g.cupo_maximo,COUNT(DISTINCT i.alumno) inscritos FROM grupos g LEFT JOIN materia_profesor mp ON mp.grupo=g.id LEFT JOIN inscripciones i ON i.asignacion=mp.id WHERE g.id=? GROUP BY g.id,g.cupo_maximo");$c->execute([$gid]);$cap=$c->fetch();if(!$cap||$cap['inscritos'] >= $cap['cupo_maximo'])throw new Exception('El grupo alcanzó su cupo máximo.');auditUser($pdo);$s=$pdo->prepare('INSERT INTO inscripciones(alumno,asignacion,estatus) VALUES(?,?,\'cursando\')');$s->execute([$al,$as]);$mensaje='Alumno inscrito.';} }}catch(PDOException $e){$error=true;$mensaje=friendly($e);}catch(Exception $e){$error=true;$mensaje=$e->getMessage();}$periodos=$pdo->query('SELECT * FROM periodos_escolares ORDER BY fecha_inicio DESC')->fetchAll();$grupos=$pdo->query('SELECT g.*,p.nombre periodo FROM grupos g JOIN periodos_escolares p ON p.id=g.id_periodo ORDER BY p.fecha_inicio DESC,g.nombre')->fetchAll();$profesores=$pdo->query('SELECT id,nombre,num_empleado FROM profesores WHERE estado=1 ORDER BY nombre')->fetchAll();$materias=$pdo->query('SELECT id,nombre,clave FROM materias ORDER BY nombre')->fetchAll();$asignaciones=$pdo->query('SELECT mp.id,m.nombre materia,p.nombre profesor,g.nombre grupo,pe.nombre periodo FROM materia_profesor mp JOIN materias m ON m.id=mp.materia JOIN profesores p ON p.id=mp.profesor JOIN grupos g ON g.id=mp.grupo JOIN periodos_escolares pe ON pe.id=g.id_periodo ORDER BY pe.fecha_inicio DESC,g.nombre,m.nombre')->fetchAll();$alumnos=$pdo->query('SELECT id,nombre,correo_institucional FROM alumnos WHERE estado=1 ORDER BY nombre')->fetchAll();
